us","type":"uint8"},{"indexed":false,"internalType":"string","name":"data","type":"string"}],"name":"QuestUpdate","type":"event"},{"anonymous":false,"inputs":[{"indexed":true,"internalType":"uint256","name":"areaLocation","type":"uint256"},{"indexed":false,"internalType":"uint64","name":"blockNumber","type":"uint64"}],"name":"RandomEvent","type":"event"},{"anonymous":false,"inputs":[{"indexed":true,"internalType":"uint256","name":"characterId","type":"uint256"},{"indexed":false,"internalType":"uint256","name":"gearId","type":"uint256"}],"name":"Recycle","type":"event"},{"anonymous":false,"inputs":[{"indexed":true,"internalType":"uint256","name":"deadCharacterId","type":"uint256"},{"indexed":false,"internalType":"uint256","name":"newCharacterId","type":"uint256"}],"name":"Resurrect","type":"event"},{"anonymous":false,"inputs":[{"indexed":true,"internalType":"uint256","name":"location","type":"uint256"},{"indexed":false,"internalType":"bytes32","name":"blockHash","type":"bytes32"},{"indexed":false,"internalType":"uint8","name":"exits","type":"uint8"},{"indexed":false,"internalType":"uint8","name":"kind","type":"uint8"}],"name":"RoomActualised","type":"event"},{"anonymous":false,"inputs":[{"indexed":true,"internalType":"uint256","name":"location","type":"uint256"},{"indexed":false,"internalType":"uint64","name":"blockNumber","type":"uint64"},{"indexed":false,"internalType":"uint8","name":"direction","type":"uint8"}],"name":"RoomDiscovered","type":"event"},{"anonymous":false,"inputs":[{"indexed":true,"internalType":"uint256","name":"location","type":"uint256"},{"indexed":true,"internalType":"address","name":"owner","type":"address"},{"indexed":false,"internalType":"uint256","name":"id","type":"uint256"},{"indexed":false,"internalType":"uint256","name":"amount","type":"uint256"}],"name":"RoomIncome","type":"event"},{"anonymous":false,"inputs":[{"indexed":true,"internalType":"uint256","name":"location","type":"uint256"},{"indexed":false,"internalType":"string","name":"name","type":"string"},{"indexed":false,"internalType":"uint256","name":"characterId","type":"uint256"}],"name":"RoomName","type":"event"},{"anonymous":false,"inputs":[{"indexed":true,"internalType":"address","name":"owner","type":"address"},{"indexed":false,"internalType":"uint256","name":"tax","type":"uint256"},{"indexed":false,"internalType":"uint256","name":"newDueDate","type":"uint256"}],"name":"RoomTaxPay","type":"event"},{"inputs":[{"internalType":"uint256","name":"location","type":"uint256"}],"name":"actualiseRoom","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"uint256","name":"characterId","type":"uint256"},{"internalType":"uint256","name":"fromLocation","type":"uint256"},{"internalType":"uint8","name":"direction","type":"uint8"}],"name":"discoverAt","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"address","name":"sender","type":"address"},{"internalType":"uint256","name":"characterId","type":"uint256"},{"internalType":"string","name":"name","type":"string"},{"internalType":"uint8","name":"class","type":"uint8"},{"internalType":"uint256","name":"location","type":"uint256"}],"name":"enter","outputs":[],"stateMutability":"payable","type":"function"},{"inputs":[{"internalType":"uint256","name":"characterId","type":"uint256"}],"name":"exit","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"uint256","name":"characterId","type":"uint256"},{"internalType":"uint8","name":"direction","type":"uint8"}],"name":"move","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"uint256","name":"characterId","type":"uint256"},{"internalType":"uint8[]","name":"directions","type":"uint8[]"}],"name":"movePath","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"uint256","name":"characterId","type":"uint256"},{"internalType":"uint256","name":"teleportLocation","type":"uint256"}],"name":"teleport","outputs":[],"stateMutability":"nonpayable","type":"function"}],"devdoc":{"kind":"dev","methods":{"discoverAt(uint256,uint256,uint8)":{"details":"Discovery decoupled from on-chain movement. Off-chain the backend is the authority on the character's position; movement between already-discovered rooms emits no transaction. Only crossing into an undiscovered room hits the chain, because that is where items live: _discoverRoom burns FRAGMENTS, mints the Room NFT and arms the commit-reveal monster seed. The spatial anti-cheat invariant is preserved at the contract level: `fromLocation` must be a discovered room with an open exit toward `direction` (validated by _moveTo), and the target must still be undiscovered. The only relaxation versus `move` is that we trust the caller (the player's wallet, gated by the off-chain backend) about which discovered room the character currently stands in, instead of reading a stale on-chain `character.location`. We re-sync the on-chain location to `fromLocation` before discovering so the numActiveCharacters bookkeeping in _move stays coherent across discovery points."}},"version":1},"userdoc":{"kind":"user","methods":{},"version":1}},"settings":{"compilationTarget":{"src/dungeon/DungeonMovementFacet.sol":"DungeonMovementFacet"},"evmVersion":"paris","libraries":{},"metadata":{"bytecodeHash":"ipfs","useLiteralContent":true},"optimizer":{"details":{"constantOptimizer":true,"cse":true,"deduplicate":true,"inliner":true,"jumpdestRemover":true,"orderLiterals":true,"peephole":true,"yul":true,"yulDetails":{"optimizerSteps":"dhfoDgvulfnTUtnIf:fDnTOc","stackAllocation":true}},"runs":1},"remappings":[],"viaIR":true},"sources":{"hardhat-deploy/solc_0.8/proxy/Proxied.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

abstract contract Proxied {
    /// @notice to be used by initialisation / postUpgrade function so that only the proxy's admin can execute them
    /// It also allows these functions to be called inside a contructor
    /// even if the contract is meant to be used without proxy
    modifier proxied() {
        address proxyAdminAddress = _proxyAdmin();
        // With hardhat-deploy proxies
        // the proxyAdminAddress is zero only for the implementation contract
        // if the implementation contract want to be used as a standalone/immutable contract
        // it simply has to execute the `proxied` function
        // This ensure the proxyAdminAddress is never zero post deployment
        // And allow you to keep the same code for both proxied contract and immutable contract
        if (proxyAdminAddress == address(0)) {
            // ensure can not be called twice when used outside of proxy : no admin
            // solhint-disable-next-line security/no-inline-assembly
            assembly {
                sstore(
                    0xb53127684a568b3173ae13b9f8a6016e243e63b6e8ee1178d6a717850b5d6103,
                    0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF
                )
            }
        } else {
            require(msg.sender == proxyAdminAddress);
        }
        _;
    }

    modifier onlyProxyAdmin() {
        require(msg.sender == _proxyAdmin(), "NOT_AUTHORIZED");
        _;
    }

    function _proxyAdmin() internal view returns (address ownerAddress) {
        // solhint-disable-next-line security/no-inline-assembly
        assembly {
            ownerAddress := sload(0xb53127684a568b3173ae13b9f8a6016e243e63b6e8ee1178d6a717850b5d6103)
        }
    }
}
