pragma solidity 0.8.20;

contract CharactersDataLayout {
    uint256 nextId;
    mapping(uint256 => address) _owners;
    mapping(address => uint256) _numPerOwners;
    mapping(uint256 => mapping(address => uint256)) _subOwner;
    mapping(uint256 => mapping(address => uint256)) _data;

    // Roles — appended to preserve upgrade storage layout.
    // _minter: contract allowed to mint characters (Player).
    // _dungeon: contract allowed to mutate in-dungeon state (Diamond holder).
    address _minter;
    address _dungeon;
    mapping(uint256 => address) _approved;
    mapping(address => mapping(address => bool)) _operators;
}
","keccak256":"0x86c2734d0dad665ea4d2cfd8dd0b11ee3bb93bb9fbc1f063ed6df14d11fec7a6","license":"MIT"},"src/diamond/DiamondStorageContract.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

/**
 * @dev Layout MUST mirror hardhat-deploy LibDiamond — hardhat-deploy writes
 * contractOwner at struct slot 4. Any divergence makes onlyOwner read the
 * wrong slot and reject every call.
 * Reference: node_modules/hardhat-deploy/solc_0.8/diamond/libraries/LibDiamond.sol
 */
abstract contract DiamondStorageContract {

    struct FacetAddressAndPosition {
        address facetAddress;
        uint96 functionSelectorPosition;
    }

    struct FacetFunctionSelectors {
        bytes4[] functionSelectors;
        uint256 facetAddressPosition;
    }

    struct DiamondStorage {
        mapping(bytes4 => FacetAddressAndPosition) selectorToFacetAndPosition;
        mapping(address => FacetFunctionSelectors) facetFunctionSelectors;
        address[] facetAddresses;
        mapping(bytes4 => bool) supportedInterfaces;
        address contractOwner;
    }

    // keccak256("diamond.standard.diamond.storage")
    bytes32 constant DIAMOND_STORAGE_POSITION = 0xc8fcad8db84d3cc18b4c41d551ea0ee66dd599cde068d998e57d5e09332c131c;

    function diamondStorage() internal pure returns (DiamondStorage storage ds) {
        bytes32 position = DIAMOND_STORAGE_POSITION;
        assembly {
            ds.slot := position
        }
    }
}
