pragma solidity 0.8.20;

/// @notice Skin pricing & treasury for Gears, kept in diamond storage so that
/// adding this mixin to the upgradeable Gears contract cannot shift its
/// existing storage layout.
abstract contract GearSkins {
    // Derived inline so the slot is auditable from source. Note: this changes
    // the storage slot away from the previous magic constant. Any skin price
    // / treasury already configured on-chain must be re-set via the admin
    // setters after this upgrade lands. Inline derivation also catches typos
    // at compile time, eliminating the magic-number drift risk.
    bytes32 internal constant GEARSKINS_STORAGE_SLOT =
        keccak256("ethernal.gearskins.v1");

    struct GearSkinsStorage {
        address payable treasury;
        mapping(uint32 => uint128) priceWei; // priceWei[skinId] = price; 0 means free/disabled
    }

    event SkinTreasuryUpdated(address indexed treasury);
    event SkinPriceUpdated(uint32 indexed skinId, uint128 priceWei);
    event SkinApplied(uint256 indexed gearId, uint32 indexed skinId, address indexed payer, uint256 paid);

    function _gsStorage() private pure returns (GearSkinsStorage storage gs) {
        bytes32 slot = GEARSKINS_STORAGE_SLOT;
        // solhint-disable-next-line no-inline-assembly
        assembly {
            gs.slot := slot
        }
    }

    function _setSkinTreasury(address payable treasury) internal {
        _gsStorage().treasury = treasury;
        emit SkinTreasuryUpdated(treasury);
    }

    function _setSkinPrice(uint32 skinId, uint128 priceWei) internal {
        _gsStorage().priceWei[skinId] = priceWei;
        emit SkinPriceUpdated(skinId, priceWei);
    }

    function getSkinTreasury() external view returns (address) {
        return _gsStorage().treasury;
    }

    function getSkinPrice(uint32 skinId) external view returns (uint128) {
        return _gsStorage().priceWei[skinId];
    }

    /// @dev Reverts if the skin is not for sale (price == 0) or if msg.value is wrong.
    /// Does NOT touch gear data — caller must update gear storage separately
    /// (this keeps payment logic decoupled from token logic).
    function _payForSkin(uint256 gearId, uint32 skinId) internal {
        require(skinId != 0, "skinId 0 reserved");
        GearSkinsStorage storage gs = _gsStorage();
        uint256 price = uint256(gs.priceWei[skinId]);
        require(price > 0, "skin not for sale");
        require(msg.value == price, "wrong value");
        address payable treasury = gs.treasury;
        require(treasury != address(0), "treasury unset");
        // Effects done; interaction last (CEI).
        (bool ok, ) = treasury.call{value: price}("");
        require(ok, "treasury transfer failed");
        emit SkinApplied(gearId, skinId, msg.sender, price);
    }
}
","keccak256":"0x71650705a707d85ebc4a514e6cb6065b44557e6b0eb61b577242c805b74404f9","license":"MIT"},"src/tokens/Gears.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

import "./ERC721Token.sol";
import "./ERC2981Royalties.sol";
import "./GearSkins.sol";

contract Gears is ERC721Token, ERC2981Royalties, GearSkins {
    function postUpgrade(address dungeon) public override {
        super.postUpgrade(dungeon);
    }

    // --- Royalties (EIP-2981) ---
    function setRoyalty(address receiver, uint96 bps) external onlyProxyAdmin {
        _setRoyalty(receiver, bps);
    }

    function supportsInterface(bytes4 interfaceId) external pure returns (bool) {
        return interfaceId == 0x01ffc9a7 /* ERC-165 */
            || _supportsRoyaltyInterface(interfaceId);
    }

    // --- Skins (admin) ---
    function setSkinTreasury(address payable treasury) external onlyProxyAdmin {
        _setSkinTreasury(treasury);
    }

    function setSkinPrice(uint32 skinId, uint128 priceWei) external onlyProxyAdmin {
        _setSkinPrice(skinId, priceWei);
    }

    // --- Skins (player) ---
    /// @notice Apply a skin to a gear. Requires the caller to be the ERC-721
    /// owner or an approved operator. Pays the catalog price to the treasury.
    /// The skin is encoded into the gear data at bits [160..192], preserving
    /// every other field. Skin ID 0 is reserved as "default".
    ///
    /// NOTE: While a gear is held inside the Dungeon vault, the ERC-721 owner
    /// is the Dungeon contract. To let players apply skins on vaulted gears,
    /// add a Dungeon facet that (a) verifies sub-ownership of the character
    /// and gear, then (b) calls this function as an approved operator.
    function applySkin(uint256 gearId, uint32 skinId) external payable {
        address owner = _owners[gearId];
        require(owner != address(0), "gear does not exist");
        require(
            owner == msg.sender || _operatorsForAll[owner][msg.sender],
            "NOT_AUTHORIZED_SKIN"
        );

        _payForSkin(gearId, skinId);

        // Update gear data: clear bits [160..192] and stamp skinId.
        uint256 data = _data[gearId];
        uint256 mask = uint256(0xFFFFFFFF) << 160;
        data = (data & ~mask) | (uint256(skinId) << 160);
        _data[gearId] = data;
        emit DataUpdate(gearId, data);
    }
}
